-- Mini e-Procurement: ข้อมูลตั้งต้น (seed) insert script for SQL Server (T-SQL).
-- Generated from design/03-domain-data/seed-data/*.csv (the CSV files are the source of truth; do not edit this file).
-- Run on a database where sql/schema.sql was applied and that is empty:
--   sqlcmd -S <server> -d <db> -f 65001 -b -i sql/seed-data.sql
-- (-f 65001 reads the file as UTF-8; the Thai text needs it.) Ids are inserted explicitly (IDENTITY_INSERT).
SET NOCOUNT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
BEGIN TRAN;
-- department (3 rows)
SET IDENTITY_INSERT department ON;
INSERT department (department_id, code, name_th, is_active) VALUES (1, N'IT', N'ไอที', 1);
INSERT department (department_id, code, name_th, is_active) VALUES (2, N'OPS', N'ปฏิบัติการ', 1);
INSERT department (department_id, code, name_th, is_active) VALUES (3, N'FIN', N'การเงินและบัญชี', 1);
SET IDENTITY_INSERT department OFF;
-- app_user (1 rows)
SET IDENTITY_INSERT app_user ON;
INSERT app_user (user_id, department_id, full_name, email, role_code, is_active) VALUES (1, 1, N'ผู้ดูแลระบบ', N'admin@example.test', N'ADMIN', 1);
SET IDENTITY_INSERT app_user OFF;
COMMIT;
GO
PRINT 'seed data loaded';
GO
